QUOTES = [a + " " + b for a in OPENERS for b in ACTIONS]

def new_state():
    return {"version":1,"tasks":[],"wins":0,"quotes_seen":[],"quote":None}

def validate(data):
    if not isinstance(data,dict) or data.get('version') != 1:
        raise ValueError('지원하지 않는 기록 파일입니다.')
    tasks=data.get('tasks',[])
    if not isinstance(tasks,list) or len(tasks)>200: raise ValueError('할 일은 최대 200개입니다.')
    clean=new_state()
    for t in tasks:
        title=str(t['title']).strip()[:100]
        steps=t['steps']
        if not title or not isinstance(steps,list) or not 1<=len(steps)<=12: raise ValueError('할 일 형식이 올바르지 않습니다.')
        done=int(t.get('done',0)); deferred=int(t.get('deferred',0))
        if not 0<=done<=len(steps) or not 0<=deferred<=10000: raise ValueError('기록 값이 올바르지 않습니다.')
        clean['tasks'].append(dict(id=uuid.uuid4().hex,title=title,steps=[str(s)[:150] for s in steps],done=done,deferred=deferred,created=str(t.get('created',''))[:40]))
    clean['wins']=max(0,min(100000,int(data.get('wins',0))))
    return clean

def power(tasks):
    return max((1 + t['deferred'] for t in tasks if t['done']<len(t['steps'])), default=0)

def next_quote(data):
    seen=set(data.get('quotes_seen',[]))
    options=[i for i in range(len(QUOTES)) if i not in seen]
    if not options: seen=set(); options=list(range(len(QUOTES)))
    i=random.choice(options); seen.add(i)
    data['quotes_seen']=sorted(seen); data['quote']=i

@st.cache_resource
def database():
    con=sqlite3.connect(str(Path(__file__).with_name('mirum_records.sqlite3')),check_same_thread=False)
    con.execute('CREATE TABLE IF NOT EXISTS saves (token TEXT PRIMARY KEY, payload TEXT NOT NULL)')
    con.commit()
    return con

token=str(st.query_params.get('room',''))
if not (len(token)==48 and all(c in '0123456789abcdef' for c in token)):
    token=secrets.token_hex(24); st.query_params['room']=token
if st.session_state.get('token')!=token:
    row=database().execute('SELECT payload FROM saves WHERE token=?',(token,)).fetchone()
    st.session_state.data=json.loads(row[0]) if row else new_state()
    st.session_state.token=token
D=st.session_state.data

def save():
    with database():
        database().execute('INSERT OR REPLACE INTO saves VALUES (?,?)',(token,json.dumps(D,ensure_ascii=False)))

def refresh():
    save(); st.rerun()

